def subtract(a, b):
    # Filter out empty intervals
    a = [interval for interval in a if interval[0] < interval[1]]
    b = [interval for interval in b if interval[0] < interval[1]]

    if not a:
        return []

    # Merge overlapping intervals in both lists
    def merge_intervals(intervals):
        if not intervals:
            return []

        sorted_intervals = sorted(intervals)
        merged = [sorted_intervals[0]]

        for current in sorted_intervals[1:]:
            last = merged[-1]
            if current[0] <= last[1]:
                # Overlapping or touching, merge them
                merged[-1] = [last[0], max(last[1], current[1])]
            else:
                merged.append(current)

        return merged

    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    if not b_merged:
        return a_merged

    # Subtract b from a
    result = []

    for a_interval in a_merged:
        current_ranges = [a_interval]

        for b_interval in b_merged:
            new_ranges = []
            for curr in current_ranges:
                # Check if b_interval overlaps with curr
                if b_interval[1] <= curr[0] or b_interval[0] >= curr[1]:
                    # No overlap
                    new_ranges.append(curr)
                else:
                    # There is overlap, split curr
                    if curr[0] < b_interval[0]:
                        new_ranges.append([curr[0], b_interval[0]])
                    if curr[1] > b_interval[1]:
                        new_ranges.append([b_interval[1], curr[1]])
            current_ranges = new_ranges

        result.extend(current_ranges)

    # Sort and merge touching intervals
    if result:
        result = merge_intervals(result)

    return result

